CREATE OR REPLACE FUNCTION public.skip_stale_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  new_stamp text;
  old_stamp text;
BEGIN
  IF NEW.row_version IS NULL OR NEW.row_version = 0 OR OLD.row_version IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.row_version < OLD.row_version THEN
    RETURN NULL;
  END IF;

  IF NEW.row_version = OLD.row_version THEN
    new_stamp := to_jsonb(NEW) ->> 'updated_at';
    old_stamp := to_jsonb(OLD) ->> 'updated_at';
    IF new_stamp IS NOT NULL AND old_stamp IS NOT NULL AND new_stamp < old_stamp THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.products_bump_row_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.row_version := COALESCE(OLD.row_version, 0) + 1;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_product_price_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  lifecycle_enabled boolean := false;
  has_stock boolean := false;
  automatic_lifecycle_change boolean := false;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' AND NOT public.has_perm('can_add_new_product') THEN
    RAISE EXCEPTION 'PERMISSION_DENIED_PRODUCT';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF (COALESCE(NEW.selling_price,0) <> COALESCE(OLD.selling_price,0)
        OR COALESCE(NEW.cost_price,0) <> COALESCE(OLD.cost_price,0)
        OR COALESCE(NEW.ecom_price,-1) IS DISTINCT FROM COALESCE(OLD.ecom_price,-1))
       AND NOT public.has_perm('can_edit_product_price') THEN
      RAISE EXCEPTION 'PERMISSION_DENIED_PRICE';
    END IF;
    IF (NEW.name IS DISTINCT FROM OLD.name OR NEW.sku IS DISTINCT FROM OLD.sku
        OR NEW.barcode IS DISTINCT FROM OLD.barcode OR NEW.category IS DISTINCT FROM OLD.category
        OR NEW.sub_category IS DISTINCT FROM OLD.sub_category
        OR NEW.product_group IS DISTINCT FROM OLD.product_group OR NEW.brand IS DISTINCT FROM OLD.brand
        OR NEW.unit IS DISTINCT FROM OLD.unit OR NEW.packs IS DISTINCT FROM OLD.packs
        OR NEW.reorder_level IS DISTINCT FROM OLD.reorder_level OR NEW.tax_rate IS DISTINCT FROM OLD.tax_rate)
       AND NOT public.has_perm('can_edit_product_details') THEN
      RAISE EXCEPTION 'PERMISSION_DENIED_PRODUCT_DETAILS';
    END IF;
    IF (NEW.barcode_aliases IS DISTINCT FROM OLD.barcode_aliases
        OR NEW.barcode_variants IS DISTINCT FROM OLD.barcode_variants)
       AND NOT public.has_perm('can_link_product_barcode') THEN
      RAISE EXCEPTION 'PERMISSION_DENIED_PRODUCT_BARCODE';
    END IF;
    IF NEW.ecom_visible IS DISTINCT FROM OLD.ecom_visible
       AND NOT public.has_perm('can_publish_product') THEN
      RAISE EXCEPTION 'PERMISSION_DENIED_PRODUCT_PUBLISH';
    END IF;
    IF NEW.is_archived IS DISTINCT FROM OLD.is_archived THEN
      SELECT COALESCE((integration_settings ->> 'autoArchiveZeroStock')::boolean, true)
        INTO lifecycle_enabled
        FROM public.pos_settings
       WHERE id = 1;
      SELECT EXISTS (
        SELECT 1
          FROM jsonb_each_text(COALESCE(NEW.stock_by_store, '{}'::jsonb))
         WHERE value ~ '^-?[0-9]+([.][0-9]+)?$'
           AND value::numeric > 0
      ) INTO has_stock;
      automatic_lifecycle_change := lifecycle_enabled
        AND (NEW.stock_by_store IS DISTINCT FROM OLD.stock_by_store OR pg_trigger_depth() > 1)
        AND NEW.is_archived = NOT has_stock;

      IF NOT automatic_lifecycle_change THEN
        IF NEW.is_archived AND NOT public.has_perm('can_archive_product') THEN
          RAISE EXCEPTION 'PERMISSION_DENIED_PRODUCT_ARCHIVE';
        END IF;
        IF NOT NEW.is_archived AND NOT public.has_perm('can_restore_product') THEN
          RAISE EXCEPTION 'PERMISSION_DENIED_PRODUCT_RESTORE';
        END IF;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.apply_zero_stock_catalog_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE enabled boolean; net_stock numeric;
BEGIN
  SELECT lower(COALESCE(integration_settings ->> 'autoArchiveZeroStock', 'true')) = 'true'
    INTO enabled FROM public.pos_settings WHERE id = 1;
  IF NOT COALESCE(enabled, true) OR NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
  IF jsonb_typeof(NEW.stock_by_store) IS DISTINCT FROM 'object' THEN RETURN NEW; END IF;
  SELECT COALESCE(sum(CASE WHEN value ~ '^-?[0-9]+([.][0-9]+)?$' THEN value::numeric ELSE 0 END), 0)
    INTO net_stock FROM jsonb_each_text(NEW.stock_by_store);
  NEW.is_archived := net_stock <= 0;
  NEW.archived_at := CASE WHEN NEW.is_archived THEN COALESCE(NEW.archived_at, now()) ELSE NULL END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.products_canonicalize_branch_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  new.stock_by_store := public.canonical_stock_by_store(new.stock_by_store);
  select coalesce(sum(case when jsonb_typeof(value) = 'number' then (value #>> '{}')::numeric else 0 end), 0)
    into new.stock_quantity
    from jsonb_each(new.stock_by_store);
  if new.owner_store_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    new.owner_store_id := lower(new.owner_store_id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.assign_product_sku()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_number bigint;
  v_explicit_number bigint;
begin
  if nullif(trim(coalesce(new.sku, '')), '') is not null then
    v_explicit_number := nullif(substring(new.sku from '([0-9]+)$'), '')::bigint;
    if v_explicit_number is not null then
      insert into public.sku_number_state (singleton, next_value)
      values (true, v_explicit_number + 1)
      on conflict (singleton) do update
        set next_value = greatest(public.sku_number_state.next_value, excluded.next_value),
            updated_at = now();
    end if;
    return new;
  end if;
  insert into public.sku_number_state (singleton, next_value)
  values (true, 1)
  on conflict (singleton) do nothing;
  select next_value into v_number
    from public.sku_number_state
   where singleton = true
   for update;
  update public.sku_number_state
     set next_value = v_number + 1,
         updated_at = now()
   where singleton = true;
  new.sku := 'SKU-' || lpad(v_number::text, 6, '0');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_product_master_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_old jsonb; v_new jsonb; v_owner text; v_revision bigint;
BEGIN
  v_old:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD)-'stock_quantity'-'stock_by_store' END;
  v_new:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW)-'stock_quantity'-'stock_by_store' END;
  IF TG_OP='UPDATE' AND v_old IS NOT DISTINCT FROM v_new THEN RETURN NEW; END IF;
  v_owner:=COALESCE(NEW.owner_store_id,OLD.owner_store_id);
  v_revision:=COALESCE(NEW.row_version,OLD.row_version,1);
  INSERT INTO public.change_history(
    entity_type,entity_id,action,old_value,new_value,revision,scope_type,scope_id,
    changed_by,source_application,device_id,terminal_id)
  VALUES('products',COALESCE(NEW.id,OLD.id)::text,lower(TG_OP),v_old,v_new,v_revision,
    CASE WHEN NULLIF(v_owner,'') IS NULL THEN 'GLOBAL' ELSE 'BRANCH' END,NULLIF(v_owner,''),
    NULLIF(current_setting('pos.updated_by',true),''),
    COALESCE(NULLIF(current_setting('pos.source_application',true),''),'web'),
    NULLIF(current_setting('pos.device_id',true),''),NULLIF(current_setting('pos.sync_terminal',true),''));
  RETURN COALESCE(NEW,OLD);
END $function$

CREATE OR REPLACE FUNCTION private.pos_sync_wake_from_feed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_topic text; v_key text; v_seen jsonb;
BEGIN
  IF NEW.organization_id <> 'default' THEN RETURN NULL; END IF;
  v_topic := CASE
    WHEN NEW.terminal_id IS NOT NULL THEN 'pos-sync:default:terminal:' || NEW.terminal_id
    WHEN NEW.branch_id='global' THEN 'pos-sync:default:global'
    ELSE 'pos-sync:default:branch:' || NEW.branch_id END;
  IF v_topic IS NULL THEN RETURN NULL; END IF;
  v_key := v_topic || ':' || NEW.table_name;
  v_seen := COALESCE(NULLIF(current_setting('pos.sync_wake_sent',true),''),'{}')::jsonb;
  -- One table/topic hint per transaction, even when 500 audit rows are inserted.
  IF v_seen ? v_key THEN RETURN NULL; END IF;
  PERFORM realtime.send(jsonb_build_object('table',NEW.table_name),'sync_changed',v_topic,true);
  PERFORM set_config('pos.sync_wake_sent',(v_seen || jsonb_build_object(v_key,true))::text,true);
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  -- Notifications are best effort; never roll back a sale for a socket outage.
  RAISE WARNING 'POS sync notification unavailable [%]', SQLSTATE;
  RETURN NULL;
END $function$

